// Browser input and presentation only; score, inventory and Snake live on the server.
export function createSessionUI({root,commands}){
  const host=document.createElement('div');host.id='session-ui';host.innerHTML=`<aside class="room-badge"><b id="session-code"></b><span id="session-count"></span><button id="session-mic" aria-label="打开麦克风">麦克风关</button></aside><section id="session-lobby" hidden><b id="session-status"></b><button id="session-bell">开始上课</button></section><dialog id="locker-dialog" class="sheet"><h2>更衣柜</h2><div class="segmented"><button data-choice="student">学生</button><button data-choice="teacher">想当老师</button></div><button id="locker-close" class="primary-button">完成</button></dialog><section id="computer-desktop" hidden aria-label="电脑桌面"><header><span>校园电脑</span><button id="computer-close" aria-label="离开电脑">E 关闭</button></header><div class="desktop-apps"><button data-app="study"><span class="study-icon">▤</span>学习</button><button data-app="snake"><span class="snake-icon">▰</span>贪吃蛇</button></div><div id="study-window" hidden><h3>课堂练习</h3><p>请阅读课本，完成今日作业。</p></div><div id="snake-window" hidden><div>得分 <b id="snake-score">0</b><button id="snake-restart">重新开始</button></div><canvas id="snake-screen" width="448" height="320"></canvas><div class="snake-directions"><button data-dir="up">↑</button><button data-dir="left">←</button><button data-dir="down">↓</button><button data-dir="right">→</button></div></div><footer>方向键 / WASD</footer></section><section id="touch-controls" hidden><div id="touch-stick" aria-label="移动"><i></i></div><div id="touch-look" aria-label="拖动转向"></div><div class="touch-actions"><button id="touch-e">互动</button><button id="touch-use">使用</button><button id="touch-crawl">爬行</button></div></section>`;root.append(host);
  const $=s=>host.querySelector(s),listen=(el,event,fn)=>{el.addEventListener(event,fn);cleanups.push(()=>el.removeEventListener(event,fn));},cleanups=[];
  let computer=false,touchSide=0,touchForward=0,crawl=false,stickId=null,lookId=null,lookPoint=null;
  listen($('#session-bell'),'click',()=>commands.bell());listen($('#session-mic'),'click',()=>commands.mic());
  for(const b of host.querySelectorAll('[data-choice]'))listen(b,'click',()=>commands.preference(b.dataset.choice));
  listen($('#locker-close'),'click',()=>{$('#locker-dialog').close();commands.resumeLook();});
  listen($('#computer-close'),'click',()=>commands.stopComputer());for(const b of host.querySelectorAll('[data-app]'))listen(b,'click',()=>commands.app(b.dataset.app));
  for(const b of host.querySelectorAll('[data-dir]'))listen(b,'pointerdown',e=>{e.preventDefault();commands.direction(b.dataset.dir);});listen($('#snake-restart'),'click',()=>commands.app('snake'));
  const touch=matchMedia('(pointer: coarse), (max-width: 820px)').matches||navigator.maxTouchPoints>0;$('#touch-controls').hidden=!touch;
  const stick=$('#touch-stick');function updateStick(e){const r=stick.getBoundingClientRect(),dx=e.clientX-r.x-r.width/2,dy=e.clientY-r.y-r.height/2,d=Math.max(42,Math.hypot(dx,dy));touchSide=dx/d;touchForward=-dy/d;stick.firstElementChild.style.transform=`translate(${touchSide*36}px,${-touchForward*36}px)`;}
  listen(stick,'pointerdown',e=>{e.preventDefault();stickId=e.pointerId;stick.setPointerCapture(e.pointerId);updateStick(e);});listen(stick,'pointermove',e=>{if(e.pointerId===stickId)updateStick(e);});for(const type of ['pointerup','pointercancel','lostpointercapture'])listen(stick,type,()=>{stickId=null;touchSide=touchForward=0;stick.firstElementChild.style.transform='';});
  const look=$('#touch-look');listen(look,'pointerdown',e=>{lookId=e.pointerId;lookPoint=[e.clientX,e.clientY];look.setPointerCapture(e.pointerId);});listen(look,'pointermove',e=>{if(e.pointerId!==lookId)return;commands.look((e.clientX-lookPoint[0])*1.5,(e.clientY-lookPoint[1])*1.5);lookPoint=[e.clientX,e.clientY];});for(const type of ['pointerup','pointercancel'])listen(look,type,()=>{lookId=null;});
  for(const [id,down,up]of [['#touch-e',()=>commands.interact(),()=>commands.interactEnd()],['#touch-use',()=>commands.hold(true),()=>commands.hold(false)]]){const b=$(id);listen(b,'pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);down();});listen(b,'pointerup',up);for(const type of ['pointercancel','lostpointercapture'])listen(b,type,()=>commands.cancel());}
  listen($('#touch-crawl'),'click',()=>{crawl=!crawl;$('#touch-crawl').setAttribute('aria-pressed',String(crawl));});
  function drawSnake(s){const c=$('#snake-screen'),ctx=c.getContext('2d');ctx.fillStyle='#172930';ctx.fillRect(0,0,c.width,c.height);if(!s)return;const size=s.width||s.cols||14,rows=s.height||s.rows||10,w=c.width/size,h=c.height/rows;ctx.strokeStyle='#253c43';for(let x=0;x<=size;x++){ctx.beginPath();ctx.moveTo(x*w,0);ctx.lineTo(x*w,c.height);ctx.stroke();}for(let y=0;y<=rows;y++){ctx.beginPath();ctx.moveTo(0,y*h);ctx.lineTo(c.width,y*h);ctx.stroke();}const xy=p=>Array.isArray(p)?p:[p.x,p.y];if(s.food){const [x,y]=xy(s.food);ctx.fillStyle='#f2b64c';ctx.beginPath();ctx.arc((x+.5)*w,(y+.5)*h,w*.28,0,Math.PI*2);ctx.fill();}for(const [i,p]of(s.body||[]).entries()){const[x,y]=xy(p);ctx.fillStyle=i?'#76ce94':'#c8f2cf';ctx.fillRect(x*w+2,y*h+2,w-4,h-4);}if(s.alive===false){ctx.fillStyle='#0c1827c9';ctx.fillRect(0,0,c.width,c.height);ctx.fillStyle='white';ctx.font='bold 24px sans-serif';ctx.textAlign='center';ctx.fillText('再来一次',c.width/2,c.height/2);}$('#snake-score').textContent=s.score||0;}
  return{touch,axes:()=>({side:touchSide,forward:touchForward,crawl}),get computer(){return computer;},openLocker(){commands.unlock();$('#locker-dialog').showModal();},update(s,round){const r=round.room;$('.room-badge').hidden=!r;$('#session-code').textContent=r?'房间 '+r.code:'';$('#session-count').textContent=r?`${r.members.length} / 8`:'';$('#session-mic').textContent=round.voice?.enabled?'麦克风开':'麦克风关';$('#session-mic').setAttribute('aria-label',round.voice?.enabled?'关闭麦克风':'打开麦克风');const lobby=!!r&&s.stage==='gathering';$('#session-lobby').hidden=!lobby;$('#session-status').textContent=lobby?(r.members.length<2?'等待同学加入':'在更衣柜选择身份'):'';$('#session-bell').hidden=!r||r.hostId!==r.selfId;$('#session-bell').disabled=!!r&&r.members.length<2;const next=!!s.player.computerActive;if(next!==computer){computer=next;if(next)commands.unlock();else commands.resumeLook();}$('#computer-desktop').hidden=!computer;$('#study-window').hidden=s.player.computer?.app!=='study';$('#snake-window').hidden=s.player.computer?.app!=='snake';if(computer)drawSnake(s.player.computer?.snake);$('#touch-controls').hidden=!touch||s.paused||computer;},reset(){touchSide=touchForward=0;computer=false;host.querySelectorAll('dialog[open]').forEach(d=>d.close());},dispose(){cleanups.forEach(f=>f());host.remove();}};
}
